-- Исправление вводящей в заблуждение формулировки: плата идёт за ПРИВЯЗАННОЕ
-- устройство, а не за время подключения. Прежний текст обещал, что баланс не
-- тает, пока не пользуешься VPN, — это неверно: списание останавливает только
-- отвязка устройства (кнопка в приложении).
UPDATE notification_templates
SET text_template = E'Привет! Это 404VPN — VPN без профилей и файлов: код доступа и одна кнопка.\n\nКак это работает: пополняешь баланс, получаешь код в этом боте, вводишь его в приложении. Списание посуточное и берётся за каждое привязанное устройство — пока устройство привязано, деньги идут, даже если VPN выключен. Не нужен — отвяжи устройство в приложении, списание прекратится.\n\nПриглашай друзей: за каждого получишь бонус на баланс и процент со всех его пополнений. Ссылка — в мини-приложении.\n\nВыбери сумму пополнения:',
    updated_at = now()
WHERE key = 'welcome';

UPDATE notification_templates
SET text_template = E'404VPN — быстрый VPN без профилей и настроек.\n\nКак начать:\n1. Пополни баланс кнопкой ниже.\n2. Получи код в мини-приложении, кнопка «Получить код».\n3. Введи код в приложении 404VPN и нажми «Подключить».\n\nОплата: посуточно за каждое привязанное устройство. Пока устройство привязано, списание идёт независимо от того, включён VPN или нет. Чтобы перестать платить — отвяжи устройство в приложении (кнопка на главном экране).\n\nБаланс кончился — доступ приостановится, пополнишь — вернётся.',
    updated_at = now()
WHERE key = 'help';
